// Stop early with a clear message if Settings still holds the template placeholders.
function checkSettings(s, keys) {
  const unset = keys.filter(k => !String(s[k] ?? '').trim() || String(s[k]).includes('REPLACE_ME'));
  if (unset.length) {
    throw new Error('Open the Settings node and fill in: ' + unset.join(', ') + '. They still contain REPLACE_ME placeholders.');
  }
}

// One output item per PDF attachment, so an email with three receipts gives three rows.
// The Gmail Trigger stores attachments as binary properties named attachment_0, attachment_1, ...
const emails = $('New Email').all();
const out = [];

$input.all().forEach((item, i) => {
  const s = item.json;
  if (i === 0) checkSettings(s, ['spreadsheetId', 'sheetName']);

  // Settings may not pass binary data along, so fall back to the trigger's own item.
  const binary = item.binary || (emails[i] && emails[i].binary) || {};
  const sender = (s.from && s.from.value && s.from.value[0]) || {};

  for (const [key, file] of Object.entries(binary)) {
    const name = String(file.fileName || key);
    const isPdf = /pdf/i.test(file.mimeType || '') || /\.pdf$/i.test(name);
    if (!isPdf) continue; // skip logos, signature images, .ics files...

    out.push({
      json: {
        messageId: s.id,
        threadId: s.threadId,
        fromAddr: String(sender.address || '').toLowerCase(),
        fromName: sender.name || '',
        subject: s.subject || '',
        receivedAt: s.date || '',
        fileName: name,
        minConfidence: s.minConfidence,
        processedLabelId: s.processedLabelId,
        maxChars: s.maxChars,
      },
      binary: { data: file },
      pairedItem: { item: i },
    });
  }
});

return out;

// Clean the extracted text and decide whether there is enough of it to read.
// Scanned PDFs (photos of receipts) have no text layer and come out empty.
const meta = $('Split PDFs').item.json;
const raw = String($json.text || '');
const text = raw.replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
const error = $json.error ? String($json.error.message || $json.error) : '';

return {
  json: {
    ...meta,
    text: text.slice(0, Number(meta.maxChars) || 15000),
    hasText: text.length >= 40,
    problem: error ? 'could not read PDF: ' + error : (text.length >= 40 ? '' : 'no text found (scanned image?)'),
  },
};

