// One spreadsheet row. Column names must match the header row of your sheet exactly.
// "Key" stops the same invoice being added twice (e.g. a resent email).
function gmailLink(id) { return id ? 'https://mail.google.com/mail/u/0/#all/' + id : ''; }

const m = $('Prepare Text').item.json;
const o = $json.output || {};
const min = Number(m.minConfidence) || 0.7;

const checks = [];
if (o.total === null || o.total === undefined) checks.push('no total');
if (!o.invoice_date) checks.push('no date');
if (!o.vendor_name) checks.push('no vendor');
if ((o.confidence ?? 0) < min) checks.push('low confidence');
if (o.notes) checks.push(o.notes);

const vendor = String(o.vendor_name || '').trim();
const number = String(o.invoice_number || '').trim();
const key = vendor && number
  ? (vendor + '|' + number).toLowerCase().replace(/\s+/g, ' ')
  : m.messageId + '|' + m.fileName;

return {
  json: {
    'Key': key,
    'Status': checks.length ? 'check: ' + checks.join('; ') : 'ok',
    'Type': o.document_type,
    'Vendor': vendor,
    'Invoice Number': number,
    'Invoice Date': o.invoice_date || '',
    'Due Date': o.due_date || '',
    'Currency': o.currency || '',
    'Subtotal': o.subtotal ?? '',
    'Tax': o.tax ?? '',
    'Total': o.total ?? '',
    'Payment Status': o.payment_status,
    'Category': o.category,
    'Description': o.description,
    'Vendor Tax ID': o.vendor_tax_id || '',
    'Confidence': o.confidence,
    'File Name': m.fileName,
    'From': m.fromAddr,
    'Email Subject': m.subject,
    'Received': m.receivedAt,
    'Email Link': gmailLink(m.messageId),
  },
};

